const { discardChanges } = options.getActions();

const dialogSettings = {
	title: aras.getResource('', 'common.discard_confirmationtitle')
};
const dialogMessage = aras.getResource('', 'common.discard_confirmationmessage');

const result = await ArasModules.Dialog.confirm(dialogMessage, dialogSettings);
if (result === 'ok') {
	discardChanges();
}
